import React, { useState } from 'react';
// Assuming Tailwind CSS is set up in your project

function ContactUsPage() {
  // State to manage form inputs
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    subject: '',
    message: '',
  });

  // State to manage form submission status
  const [submissionStatus, setSubmissionStatus] = useState('idle'); // 'idle', 'submitting', 'success', 'error'
  const [submissionMessage, setSubmissionMessage] = useState(''); // Message to display based on status

  // Function to handle input changes
  const handleInputChange = (event) => {
    const { name, value } = event.target;
    setFormData({
      ...formData,
      [name]: value,
    });
    // Clear status messages when user starts typing again
    if (submissionStatus !== 'idle') {
      setSubmissionStatus('idle');
      setSubmissionMessage('');
    }
  };

  // Function to handle form submission
  const handleSubmit = async (event) => {
    event.preventDefault();

    setSubmissionStatus('submitting');
    setSubmissionMessage('Sending message...');

    // --- Implement form submission logic here ---
    // This involves sending the formData to a backend API endpoint
    // The backend is responsible for sending the email securely.

    try {
      // Replace '/api/contact' with the actual URL of your backend endpoint
      // This endpoint should accept a POST request with JSON body
      const response = await fetch('/api/contact', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(formData),
      });

      // Check if the response was successful (e.g., status code 2xx)
      if (response.ok) {
        const result = await response.json(); // Assuming backend returns JSON
        console.log('Success:', result);
        setSubmissionStatus('success');
        setSubmissionMessage('Message sent successfully!');
        // Clear the form after successful submission
        setFormData({
          name: '',
          email: '',
          subject: '',
          message: '',
        });
      } else {
        // Handle non-OK responses (e.g., server errors, validation errors)
        const errorData = await response.json(); // Assuming backend sends error details in JSON
        console.error('Error:', response.status, errorData);
        setSubmissionStatus('error');
        setSubmissionMessage(errorData.message || 'Failed to send message. Please try again.');
      }

    } catch (error) {
      // Handle network errors or issues with the fetch request
      console.error('Network Error:', error);
      setSubmissionStatus('error');
      setSubmissionMessage('Could not connect to the server. Please check your connection or try again later.');
    }
  };

  // Determine if the submit button should be disabled
  const isSubmitDisabled = submissionStatus === 'submitting';

  return (
    // Main container for the page content
    // Uses Tailwind for padding, background, text color, and responsiveness
    // Styles are designed to work within a parent controlling dark mode
    <div className="container mx-auto px-4 py-8 max-w-2xl bg-white dark:bg-gray-800 text-gray-900 dark:text-gray-200 rounded-lg shadow-md my-8">

      {/* Main Heading */}
      <h1 className="text-3xl md:text-4xl font-bold text-center text-blue-600 dark:text-blue-400 mb-8">
        Contact Us
      </h1>

      {/* Introduction */}
      <p className="text-lg text-center mb-6 text-gray-700 dark:text-gray-300">
        Have questions, feedback, or need support? Send us a message using the form below.
      </p>

      {/* Contact Form */}
      {/* The form element itself */}
      <form onSubmit={handleSubmit} className="space-y-6">
        {/* Name Input */}
        <div>
          <label htmlFor="name" className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
            Name
          </label>
          <input
            type="text"
            id="name"
            name="name"
            value={formData.name}
            onChange={handleInputChange}
            required // Make field required
            disabled={isSubmitDisabled} // Disable input while submitting
            className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-md shadow-sm bg-gray-50 dark:bg-gray-700 text-gray-900 dark:text-gray-100 focus:outline-none focus:ring-blue-500 dark:focus:ring-blue-400 focus:border-blue-500 dark:focus:border-blue-400 transition-colors duration-300 disabled:opacity-60 disabled:cursor-not-allowed"
          />
        </div>

        {/* Email Input */}
        <div>
          <label htmlFor="email" className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
            Email
          </label>
          <input
            type="email" // Use type="email" for basic browser validation
            id="email"
            name="email"
            value={formData.email}
            onChange={handleInputChange}
            required // Make field required
            disabled={isSubmitDisabled} // Disable input while submitting
            className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-md shadow-sm bg-gray-50 dark:bg-gray-700 text-gray-900 dark:text-gray-100 focus:outline-none focus:ring-blue-500 dark:focus:ring-blue-400 focus:border-blue-500 dark:focus:border-blue-400 transition-colors duration-300 disabled:opacity-60 disabled:cursor-not-allowed"
          />
        </div>

        {/* Subject Input */}
        <div>
          <label htmlFor="subject" className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
            Subject (Optional)
          </label>
          <input
            type="text"
            id="subject"
            name="subject"
            value={formData.subject}
            onChange={handleInputChange}
            disabled={isSubmitDisabled} // Disable input while submitting
            className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-md shadow-sm bg-gray-50 dark:bg-gray-700 text-gray-900 dark:text-gray-100 focus:outline-none focus:ring-blue-500 dark:focus:ring-blue-400 focus:border-blue-500 dark:focus:border-blue-400 transition-colors duration-300 disabled:opacity-60 disabled:cursor-not-allowed"
          />
        </div>

        {/* Message Textarea */}
        <div>
          <label htmlFor="message" className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
            Message
          </label>
          <textarea
            id="message"
            name="message"
            rows="4" // Set number of rows
            value={formData.message}
            onChange={handleInputChange}
            required // Make field required
            disabled={isSubmitDisabled} // Disable input while submitting
            className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-md shadow-sm bg-gray-50 dark:bg-gray-700 text-gray-900 dark:text-gray-100 focus:outline-none focus:ring-blue-500 dark:focus:ring-blue-400 focus:border-blue-500 dark:focus:border-blue-400 transition-colors duration-300 disabled:opacity-60 disabled:cursor-not-allowed"
          ></textarea>
        </div>

        {/* Submit Button */}
        <div>
          <button
            type="submit"
            disabled={isSubmitDisabled} // Disable button while submitting
            className="w-full flex justify-center py-2 px-4 border border-transparent rounded-md shadow-sm text-sm font-medium text-white bg-blue-600 hover:bg-blue-700 dark:bg-blue-700 dark:hover:bg-blue-600 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-blue-500 dark:focus:ring-offset-gray-800 dark:focus:ring-blue-400 transition duration-150 ease-in-out disabled:opacity-50 disabled:cursor-not-allowed"
          >
             {/* Show spinner and text when submitting */}
            {submissionStatus === 'submitting' ? (
              <svg className="animate-spin -ml-1 mr-3 h-5 w-5 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
              </svg>
            ) : null}
            {submissionStatus === 'submitting' ? 'Sending...' : 'Send Message'}
          </button>
        </div>
      </form>

      {/* Submission Status Message */}
      {submissionMessage && (
        <div className={`mt-4 p-3 rounded-md text-center ${
          submissionStatus === 'success' ? 'bg-green-100 border border-green-400 text-green-700 dark:bg-green-900 dark:border-green-700 dark:text-green-300' :
          submissionStatus === 'error' ? 'bg-red-100 border border-red-400 text-red-700 dark:bg-red-900 dark:border-red-700 dark:text-red-300' :
          'bg-gray-100 dark:bg-gray-700 text-gray-700 dark:text-gray-300' // For 'sending...' status
        }`}>
          {submissionMessage}
        </div>
      )}


      {/* Optional: Direct email link or other contact info */}
      <p className="text-center mt-8 text-gray-600 dark:text-gray-400 text-sm">
        You can also email us directly at <a href="mailto:support@yoursitename.com" className="text-blue-600 dark:text-blue-400 hover:underline">support@yoursitename.com</a>
      </p>

    </div>
  );
}

export default ContactUsPage;
